请对以下 case 进行三维加权评分。

=== case_id ===
Case-24-todo-006

=== 用户原始指令 (query.txt) ===
整个待办看完成比例,点跳应用,读日历,显示已完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个待办看完成比例,点跳应用,读日历,显示已完成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "completionRateText": {
          "type": "string",
          "description": "今日待办完成比例的展示文本。",
          "sampleValue": "75%"
        },
        "completionValue": {
          "type": "number",
          "description": "今日已完成待办数量，用于进度条当前值。",
          "sampleValue": 6
        },
        "completionTotal": {
          "type": "number",
          "description": "今日待办总数量，用于进度条总值。",
          "sampleValue": 8
        },
        "completedText": {
          "type": "string",
          "description": "今日已完成待办数量的短展示文本。",
          "sampleValue": "已完成 6"
        },
        "totalText": {
          "type": "string",
          "description": "今日全部待办数量的短展示文本。",
          "sampleValue": "共 8 项"
        }
      }
    }
  },
  "assetCandidates": []
}

